<?php
namespace App\Http\Controllers;
use App\Modules\Knowledge\Models\{KnowledgeArticle,KnowledgeAssignment,KnowledgeTracking}; use App\Tenancy\AuthorizedCoreUser; use Illuminate\Http\Request;
class KnowledgeController extends Controller { public function articles(Request $r){return view('tenant.knowledge.articles',['articles'=>KnowledgeArticle::with('assignments.tracking')->latest()->get(),'users'=>$r->attributes->get('tenantAccount')->users()->where('users.status','active')->get()]);} public function storeArticle(Request $r){KnowledgeArticle::create($r->validate(['title'=>'required|max:200','content'=>'required','category'=>'nullable|max:100','version'=>'required|integer|min:1','status'=>'required|in:draft,published,inactive']));return back();} public function assign(Request $r, KnowledgeArticle $article, AuthorizedCoreUser $users){$d=$r->validate(['core_user_id'=>'required|integer','due_at'=>'nullable|date','required'=>'nullable|boolean']);$users->ensure($r->attributes->get('tenantAccount'),$d['core_user_id']);$a=KnowledgeAssignment::create(['article_id'=>$article->id,...$d,'assigned_at'=>now(),'required'=>$r->boolean('required',true)]);KnowledgeTracking::create(['assignment_id'=>$a->id]);return back();} public function open(KnowledgeAssignment $assignment){$assignment->tracking()->updateOrCreate([],['opened_at'=>now()]);return back();} public function complete(KnowledgeAssignment $assignment){$assignment->tracking()->updateOrCreate([],['completed_at'=>now()]);return back();} public function confirm(KnowledgeAssignment $assignment){$assignment->tracking()->updateOrCreate([],['confirmed_at'=>now()]);return back();} }
